//! Golden vectors from colour-science 0.4.7, generated by
//! `tools/golden/gen_basics.py`.

use std::collections::BTreeMap;
use std::sync::LazyLock;

use looklab_color::cat::{Cat, adapt, adaptation_matrix};
use looklab_color::chart::{colorchecker24, colorchecker24_illuminant};
use looklab_color::ciede2000::delta_e_ciede2000;
use looklab_color::lab::{Lab, Lchab, lab_to_lchab, lab_to_xyz, lchab_to_lab, xyz_to_lab};
use looklab_color::spaces::RgbSpace;
use looklab_color::trc::{
    adobe_rgb_decode, adobe_rgb_encode, prophoto_decode, prophoto_encode, rec2020_decode,
    rec2020_encode, srgb_decode, srgb_encode,
};
use looklab_color::types::{Rgb, Xyy, Xyz};
use looklab_color::xyy::{Illuminant, xy_to_xyz, xyy_to_xyz, xyz_to_xyy};
use serde::de::DeserializeOwned;
use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
struct Golden {
    vectors: BTreeMap<String, Vectors>,
    spaces: BTreeMap<String, SpaceVectors>,
    cats: BTreeMap<String, CatVectors>,
    space_matrices: BTreeMap<String, SpaceGolden>,
}

#[derive(Deserialize)]
struct Vectors {
    inputs: Vec<Vec<f64>>,
    outputs: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct SpaceVectors {
    rgb_to_xyz: Vectors,
    xyz_to_rgb: Vectors,
}

#[derive(Deserialize)]
struct CatVectors {
    matrix: Vectors,
    adapt: Vectors,
}

#[derive(Deserialize)]
struct SpaceGolden {
    name: String,
    derived_rgb_to_xyz: Vec<f64>,
    derived_xyz_to_rgb: Vec<f64>,
    stored_rgb_to_xyz: Vec<f64>,
    stored_xyz_to_rgb: Vec<f64>,
}

static GOLDEN: LazyLock<Golden> = LazyLock::new(|| {
    serde_json::from_str(include_str!("golden/basics.json")).expect("golden vectors parse")
});

fn vectors(name: &str) -> &'static Vectors {
    GOLDEN
        .vectors
        .get(name)
        .unwrap_or_else(|| panic!("missing golden vector set {name}"))
}

fn assert_close(actual: f64, expected: f64) {
    let tolerance = (expected.abs() * 1e-6).max(1e-12);
    assert!(
        (actual - expected).abs() <= tolerance,
        "actual {actual:?}, expected {expected:?}"
    );
}

fn check_vectors(set: &Vectors, convert: impl Fn(&[f64]) -> Vec<f64>) {
    assert_eq!(set.inputs.len(), set.outputs.len());
    for (input, expected) in set.inputs.iter().zip(&set.outputs) {
        let actual = convert(input);
        assert_eq!(actual.len(), expected.len());
        for (actual, expected) in actual.iter().zip(expected) {
            assert_close(*actual, *expected);
        }
    }
}

fn check_named(name: &str, convert: impl Fn(&[f64]) -> Vec<f64>) {
    check_vectors(vectors(name), convert);
}

fn key_of<T: Serialize>(value: T) -> String {
    serde_json::to_value(value)
        .expect("golden key serialises")
        .as_str()
        .expect("golden key is a string")
        .to_owned()
}

fn from_key<T: DeserializeOwned>(key: &str) -> T {
    serde_json::from_value(serde_json::Value::String(key.to_owned()))
        .unwrap_or_else(|_| panic!("unknown golden key {key}"))
}

fn flatten(matrix: looklab_color::Mat3) -> [f64; 9] {
    let m = matrix.0;
    [
        m[0][0], m[0][1], m[0][2], m[1][0], m[1][1], m[1][2], m[2][0], m[2][1], m[2][2],
    ]
}

#[test]
fn xyy_conversions_match_colour_science() {
    check_named("xyz_to_xyy", |v| {
        xyz_to_xyy(Xyz::new(v[0], v[1], v[2])).to_array().to_vec()
    });
    check_named("xyy_to_xyz", |v| {
        xyy_to_xyz(Xyy {
            x: v[0],
            y: v[1],
            big_y: v[2],
        })
        .to_array()
        .to_vec()
    });
    check_named("xy_to_xyz", |v| xy_to_xyz((v[0], v[1])).to_array().to_vec());
}

type TransferFunction = (&'static str, fn(f64) -> f64);

#[test]
fn transfer_functions_match_colour_science() {
    let cases: [TransferFunction; 8] = [
        ("srgb_encode", srgb_encode),
        ("srgb_decode", srgb_decode),
        ("adobe_rgb_encode", adobe_rgb_encode),
        ("adobe_rgb_decode", adobe_rgb_decode),
        ("rec2020_encode", rec2020_encode),
        ("rec2020_decode", rec2020_decode),
        ("prophoto_encode", prophoto_encode),
        ("prophoto_decode", prophoto_decode),
    ];
    for (name, function) in cases {
        check_named(name, |v| vec![function(v[0])]);
    }
}

#[test]
fn rgb_space_conversions_match_colour_science() {
    for (key, set) in &GOLDEN.spaces {
        let space: RgbSpace = from_key(key);
        check_vectors(&set.rgb_to_xyz, |v| {
            space
                .rgb_linear_to_xyz(Rgb::new(v[0], v[1], v[2]))
                .to_array()
                .to_vec()
        });
        check_vectors(&set.xyz_to_rgb, |v| {
            space
                .xyz_to_rgb_linear(Xyz::new(v[0], v[1], v[2]))
                .to_array()
                .to_vec()
        });
    }
}

#[test]
fn space_matrices_match_derivation_and_stored_values() {
    for (key, golden) in &GOLDEN.space_matrices {
        let space: RgbSpace = from_key(key);
        assert_eq!(space.name(), golden.name);
        let to_xyz = flatten(space.to_xyz_matrix());
        let from_xyz = flatten(space.from_xyz_matrix());
        for (index, derived) in golden.derived_rgb_to_xyz.iter().enumerate() {
            assert_close(to_xyz[index], *derived);
            // colour-science stores the rounded matrices printed by the
            // colour space standard where one defines them.
            assert!((to_xyz[index] - golden.stored_rgb_to_xyz[index]).abs() < 1e-3);
        }
        for (index, derived) in golden.derived_xyz_to_rgb.iter().enumerate() {
            assert_close(from_xyz[index], *derived);
            assert!((from_xyz[index] - golden.stored_xyz_to_rgb[index]).abs() < 1e-3);
        }
    }
}

#[test]
fn chromatic_adaptation_matches_colour_science() {
    for (key, set) in &GOLDEN.cats {
        let cat: Cat = from_key(key);
        check_vectors(&set.matrix, |v| {
            flatten(adaptation_matrix(
                cat,
                Xyz::new(v[0], v[1], v[2]),
                Xyz::new(v[3], v[4], v[5]),
            ))
            .to_vec()
        });
        check_vectors(&set.adapt, |v| {
            adapt(
                Xyz::new(v[0], v[1], v[2]),
                cat,
                Xyz::new(v[3], v[4], v[5]),
                Xyz::new(v[6], v[7], v[8]),
            )
            .to_array()
            .to_vec()
        });
    }
}

#[test]
fn lab_conversions_match_colour_science() {
    check_named("xyz_to_lab", |v| {
        xyz_to_lab(Xyz::new(v[0], v[1], v[2]), Xyz::new(v[3], v[4], v[5]))
            .to_array()
            .to_vec()
    });
    check_named("lab_to_xyz", |v| {
        lab_to_xyz(Lab::new(v[0], v[1], v[2]), Xyz::new(v[3], v[4], v[5]))
            .to_array()
            .to_vec()
    });
    check_named("lab_to_lchab", |v| {
        lab_to_lchab(Lab::new(v[0], v[1], v[2])).to_array().to_vec()
    });
    check_named("lchab_to_lab", |v| {
        lchab_to_lab(Lchab::new(v[0], v[1], v[2]))
            .to_array()
            .to_vec()
    });
}

#[test]
fn ciede2000_matches_colour_science() {
    check_named("delta_e_ciede2000", |v| {
        vec![delta_e_ciede2000(
            Lab::new(v[0], v[1], v[2]),
            Lab::new(v[3], v[4], v[5]),
        )]
    });
}

#[test]
fn illuminants_match_colour_science() {
    check_named("illuminant_xyz", |v| {
        xy_to_xyz((v[0], v[1])).to_array().to_vec()
    });
    assert_eq!(Illuminant::D50.xy(), (0.3457, 0.3585));
}

#[derive(Deserialize)]
struct ChartGolden {
    illuminant_xy: [f64; 2],
    patches: Vec<ChartPatchGolden>,
}

#[derive(Deserialize)]
struct ChartPatchGolden {
    name: String,
    xyy: [f64; 3],
}

#[test]
fn chart_matches_colour_science() {
    let golden: ChartGolden = serde_json::from_str(include_str!(
        "../../../data/charts/colorchecker24_2014.json"
    ))
    .expect("chart data parses");
    let patches = colorchecker24();
    assert_eq!(patches.len(), golden.patches.len());
    for (patch, expected) in patches.iter().zip(&golden.patches) {
        assert_eq!(patch.name, expected.name);
        let xyz = xyy_to_xyz(Xyy {
            x: expected.xyy[0],
            y: expected.xyy[1],
            big_y: expected.xyy[2],
        });
        assert_close(patch.xyz.x, xyz.x);
        assert_close(patch.xyz.y, xyz.y);
        assert_close(patch.xyz.z, xyz.z);
    }
    let illuminant = colorchecker24_illuminant();
    let expected = xy_to_xyz((golden.illuminant_xy[0], golden.illuminant_xy[1]));
    assert_close(illuminant.x, expected.x);
    assert_close(illuminant.y, expected.y);
    assert_close(illuminant.z, expected.z);
}

#[test]
fn every_space_has_a_golden_derivation() {
    assert_eq!(GOLDEN.space_matrices.len(), RgbSpace::ALL.len());
    for space in RgbSpace::ALL {
        assert!(GOLDEN.space_matrices.contains_key(&key_of(space)));
    }
}
